```python
# Tool -- model decides when to call it
{"type": "tool", "name": "search_database", "parameters": {"query": "str"}}

# Resource -- application attaches it to context directly
{"type": "resource", "uri": "file:///reports/q3_summary.pdf"}

# Prompt -- reusable template, filled in with parameters
{"type": "prompt", "name": "summarize_document", "parameters": {"doc_id": "str", "length": "str"}}

# Mixing these up -- e.g. making a static reference doc a "tool" the model
# must remember to call -- creates exactly the friction this lesson warns about.
```

```python
# Harder for a model to use correctly: one broad tool with a mode switch
@server.tool()
def manage_records(mode: str, record_id: str = None, data: dict = None):
    """mode: 'create', 'update', or 'delete'"""
    ...

# Easier for a model to use correctly: three narrow, self-contained tools
@server.tool()
def create_record(data: dict):
    """Create a new record with the given field values."""
    ...

@server.tool()
def update_record(record_id: str, data: dict):
    """Update an existing record identified by record_id."""
    ...

@server.tool()
def delete_record(record_id: str):
    """Permanently delete the record identified by record_id."""
    ...
```

```python
# Listing: cheap metadata only, no content fetched yet
@server.list_resources()
def list_resources():
    return [{"uri": "file:///reports/q3.pdf", "name": "Q3 Report"}]

# Reading: fetches the actual content, only when specifically requested
@server.read_resource()
def read_resource(uri: str):
    return open(uri.replace("file://", "")).read()

# A parameterized prompt template
@server.prompt()
def summarize_document(doc_id: str, length: str = "short"):
    return f"Summarize document {doc_id} in a {length} paragraph."
```

```python
# 1. Plain function with the actual logic
def _lookup_order_status(order_id: str) -> str:
    order = db.get_order(order_id)
    return order.status if order else "not found"

# 2. Register via decorator -- SDK handles JSON-RPC plumbing
@server.tool(name="lookup_order_status",
             description="Look up the current status of an order by its id.")
def lookup_order_status(order_id: str) -> str:
    return _lookup_order_status(order_id)

# 3. Test the plain function directly, with no MCP protocol involved
def test_lookup_order_status():
    assert _lookup_order_status("ord_123") == "shipped"
```
